    return list(filter(lambda item: item % 20 == 0, values))

def solve_1(items):
    """Build and return a list containing even items."""
    even_items = []
    for value in items:
        if value % 2 == 0:
            even_items.append(value)
    return even_items

def solve_3(values):
    """Build and return a list containing even values."""
    even_values = []
    for value in values:
        if value % 4 == 0:
            even_values.append(value)
    return even_values

def solve_17(values):
    out = []
    for value in values:
        if value % 18 == 0:
            out.append(value)
    return out
